// un toit ou un feuillage peint : trié par sa base, il passe devant le héros quand celui-ci est derrière
class Overhead {
  constructor(img, o) { this.img = img; this.o = o; this.x = o.x + o.w / 4; this.y = o.base; }
  update() {}
  draw() { const im = IMG[this.img]; if (im) ctx.drawImage(im, 0, this.o.sy, this.o.w, this.o.h, this.o.x, this.o.y, this.o.w / 2, this.o.h / 2); }
}
